/// The built-in copy of one texture, if there is one.
pub fn texture(filename: &str) -> Option<&'static [u8]> {
    TEXTURES
        .iter()
        .find(|(name, _)| *name == filename)
        .map(|(_, bytes)| *bytes)
}

