/// The built-in copy of one recording, if there is one.
pub fn sound(path: &str) -> Option<&'static [u8]> {
    SOUNDS.iter().find(|(name, _)| *name == path).map(|(_, bytes)| *bytes)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_texture_blocks_toml_names_is_embedded() {
        // The two lists are maintained by hand, and the failure mode of
        // them disagreeing is a game that runs with a checkerboard where
        // a block should be -- which is easy to ship without noticing.
        for line in BLOCKS_TOML.lines() {
            for piece in line.split('"') {
                // Made at load, not embedded: see `engine::pebble_art`.
                if !piece.ends_with(".png") || crate::engine::pebble_art::is_generated(piece) {
                    continue;
                }
                assert!(
                    texture(piece).is_some(),
                    "blocks.toml refers to {piece:?}, which is not embedded"
                );
            }
        }
    }

    #[test]
    fn the_window_icon_is_embedded_too() {
        // It is not in blocks.toml -- it is not a block -- so nothing
        // else would catch it going missing.
        assert!(texture(crate::engine::texture::ICON_FILE).is_some());
    }

    #[test]
    fn nothing_embedded_is_empty() {
        for (name, bytes) in TEXTURES {
            assert!(!bytes.is_empty(), "{name} is empty");
            assert_eq!(&bytes[1..4], b"PNG", "{name} is not a PNG");
        }
    }

    #[test]
    fn no_picture_is_shipped_in_a_lazily_written_png() {
        // **The pictures were being shipped a third bigger than they
        // needed to be, in three places at once.** A PNG written by an
        // image editor at its default settings is deflated at a middling
        // level with whatever row filter the writer felt like, and 140
        // of the 188 files here were written that way: 370 KB where the
        // same pixels come to 240. That is 130 KB of every download and
        // of every APK, and it buys nothing at all -- the decoded image
        // is identical, byte for byte.
        //
        // The cloud field alone was 278 KB of it, which is the shape of
        // the problem: one 512x512 picture in a game whose other 187
        // are sixteen texels square. See `engine::texture::CloudTexture`
        // for why it is that size.
        //
        // Measured against a re-encode at full effort rather than
        // against a fixed number of bytes, because the question is "was
        // this written carelessly", not "is this file small" -- a
        // texture with more in it is allowed to be bigger. The margin
        // is generous: `image`'s encoder is not the best one that
        // exists, and the shipped set currently comes out 2% *under*
        // what it would produce.
        use image::codecs::png::{CompressionType, FilterType, PngEncoder};
        use image::ImageEncoder;
        let (mut have, mut best) = (0usize, 0usize);
        let (mut worst, mut worst_name) = (0.0f32, "");
        for (name, bytes) in TEXTURES {
            let img = image::load_from_memory(bytes).expect("an embedded png").to_rgba8();
            let mut out = Vec::new();
            PngEncoder::new_with_quality(&mut out, CompressionType::Best, FilterType::Adaptive)
                .write_image(&img, img.width(), img.height(), image::ColorType::Rgba8)
                .expect("re-encoding a picture that just decoded");
            have += bytes.len();
            best += out.len();
            let ratio = bytes.len() as f32 / out.len() as f32;
            if ratio > worst {
                worst = ratio;
                worst_name = name;
            }
        }
        assert!(
            have as f32 <= best as f32 * 1.10,
            "the pictures come to {have} bytes where a re-encode gives {best};              the worst is {worst_name} at {worst:.2}x. Run them through an              optimiser -- the pixels do not change and the download does",
        );
    }

    #[test]
    fn the_whole_lot_stays_small_enough_to_be_worth_embedding() {
        // The argument for doing this at all is that it is negligible.
        // If it stops being negligible, the argument stops holding.
        let total: usize = TEXTURES.iter().map(|(_, b)| b.len()).sum();
        assert!(total < 512 * 1024, "embedded assets have grown to {total} bytes");
    }
}
